param([string]$Root = (Resolve-Path (Join-Path $PSScriptRoot '..\\..\\..')).Path)
$ErrorActionPreference = 'Stop'; $s00 = Join-Path $Root 'planning/sprints/S00'; $srs = Join-Path $Root 'docs/MADAR_V1_Master_SRS_V1.2_Reconciled_Complete_Arabic.md'; $runbook = Join-Path $Root 'docs/MADAR_V1_V5_AI_Execution_Master_Runbook_Arabic.md'
$results = [System.Collections.Generic.List[object]]::new()
function Add-Result($id,$actual,$pass,$evidence) { $results.Add([pscustomobject]@{TestID=$id;Result=if($pass){'PASS'}else{'FAIL'};Actual=$actual;Evidence=$evidence}) }
Add-Result 'DOC-01' "SRS=$(Test-Path $srs); V5=$(Test-Path $runbook)" ((Test-Path $srs) -and (Test-Path $runbook)) 'docs/'
try { $lines=[System.IO.File]::ReadAllLines($srs); Add-Result 'DOC-02' "$($lines.Count) SRS lines readable" ($lines.Count -gt 0) 'SRS read' } catch { Add-Result 'DOC-02' $_.Exception.Message $false 'SRS read' }
$boundary=[Array]::FindIndex($lines,[Predicate[string]]{param($x)$x -match '^# الجزء الثامن'}); $ids=@(); for($i=0;$i -lt $boundary;$i++){if($lines[$i] -match '^\*\*(FR-[A-Z]+-\d{3})\*\*\s*[—-]'){$ids+=$matches[1]}}
Add-Result 'DOC-03' "$($ids.Count) canonical IDs extractable" ($ids.Count -eq 253) 'canonical SRS body'; Add-Result 'DOC-04' "Unique=$(@($ids|Select-Object -Unique).Count)" (@($ids|Select-Object -Unique).Count -eq 253) 'canonical SRS body'; Add-Result 'DOC-05' "Duplicates=$($ids.Count-@($ids|Select-Object -Unique).Count)" ($ids.Count-@($ids|Select-Object -Unique).Count -eq 0) 'canonical SRS body'
$rtm=Import-Csv (Join-Path $s00 'RTM.csv'); $blank=@($rtm|Where-Object{[string]::IsNullOrWhiteSpace($_.requirement_id)-or [string]::IsNullOrWhiteSpace($_.source_file)-or [string]::IsNullOrWhiteSpace($_.source_line)}); Add-Result 'DOC-06' "RTM rows=$($rtm.Count)" ($rtm.Count -eq 253) 'RTM.csv'; Add-Result 'DOC-07' "Blank primary references=$($blank.Count)" ($blank.Count -eq 0) 'RTM.csv'; Add-Result 'DOC-08' "Rows classified=$(@($rtm|Where-Object{[string]::IsNullOrWhiteSpace($_.classification)}).Count -eq 0)" (@($rtm|Where-Object{[string]::IsNullOrWhiteSpace($_.classification)}).Count -eq 0) 'RTM.csv'; Add-Result 'DOC-09' "V2 implementation rows=$(@($rtm|Where-Object{$_.release_scope -eq 'V2'}).Count)" (@($rtm|Where-Object{$_.release_scope -eq 'V2'}).Count -eq 0) 'RTM.csv'
$d=Get-Content (Join-Path $s00 'decisions.md') -Raw; $opens=1..9|ForEach-Object{"OPEN-{0:d2}" -f $_}; Add-Result 'DOC-10' "Open IDs found=$(@($opens|Where-Object{$d -match $_}).Count)" (@($opens|Where-Object{$d -match $_}).Count -eq 9) 'decisions.md'; Add-Result 'DOC-11' 'All baseline decision rows are OPEN' ($d -notmatch '\| OPEN-\d{2} .*\| APPROVED \|') 'decisions.md'
$files='ticket.md','repository-inventory.md','requirements-inventory.md','requirements-validation.md','RTM.csv','gap-analysis.md','decisions.md','scope.md','ownership-proposal.md','source-of-truth-matrix.md','test-cases.md','test-results.md','acceptance.md','handoff.md'; Add-Result 'DOC-15' "Present=$(@($files|Where-Object{Test-Path (Join-Path $s00 $_)}).Count)/$($files.Count)" (@($files|Where-Object{Test-Path (Join-Path $s00 $_)}).Count -eq $files.Count) 'S00 directory'; Add-Result 'DOC-17' 'RTM CSV readable' ($rtm.Count -eq 253) 'RTM.csv'; Add-Result 'DOC-19' "AGENTS exists=$(Test-Path (Join-Path $Root 'AGENTS.md'))" (Test-Path (Join-Path $Root 'AGENTS.md')) 'AGENTS.md'; Add-Result 'DOC-20' "Handoff exists=$(Test-Path (Join-Path $s00 'handoff.md'))" (Test-Path (Join-Path $s00 'handoff.md')) 'handoff.md'
$results | Format-Table -AutoSize; if($results.Result -contains 'FAIL'){exit 1}
